class Solution 
{
public:
    int climbStairs(int n) 
    {
        if ( (n==1) || (n==0) )
        {
            return n ;
        }
        int a = 0 , b = 1 , c = 0 , i = 0 ;

        for(i=0;i<n;i++)
        {
            c = a + b ;
            a = b ;
            b = c ;
        }
        return c ;
    }
};
